service.method:

UPDATE
	SUSMT
SET
  	  CHANGE_DATE = ${current.DATE}
	, CHANGE_TIME = ${current.TIME}
	, CHANGE_USER_ID = ${session.ID}
	, DEPT = ${DEPT}
	, USER_NAME_LOC = ${USER_NAME_LOC}
	, POSITION = ${POSITION}
	, COUNTRY = ${COUNTRY}
	, DATE_FORMAT = ${DATE_FORMAT}
	, EMAIL = ${EMAIL}
	, PW_RESET_FLAG = 'Y'


    , PASSWORD = ${PASSWORD}
    , PW_RESET_DATE = ${current.DATE}
    , PASS_CHECK_CNT = 0


WHERE
	HOUSE_CODE = ${HOUSE_CODE}
AND USER_ID = ${USER_ID}


UPDATE
	SADDR
SET
	  CHANGE_DATE = ${current.date}
	, CHANGE_TIME = ${current.time}
	, CHANGE_USER_ID = ${session.ID}
	, PHONE_NO1 = ${PHONE_NO1}
	, PHONE_NO2 = ${PHONE_NO2}
	, ZIP_CODE = ${ZIP_CODE}
	, ADDRESS_LOC = ${ADDRESS_LOC}
WHERE
	HOUSE_CODE = ${HOUSE_CODE}
AND CODE_NO = ${USER_ID}


INSERT INTO SUSMT
(
	  DEPT
	, USER_NAME_LOC
	, POSITION
	, COUNTRY
	, DATE_FORMAT
	, EMAIL
	, HOUSE_CODE
	, USER_ID
	, COMPANY_CODE
	, USER_TYPE
	, PW_RESET_FLAG
	, PW_RESET_DATE
	, DEL_FLAG
	, MENU_PROFILE_CODE
	, SIGN_STATUS
	, WORK_TYPE
	, PASSWORD
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
) VALUES
(
	  ${DEPT}
	, ${USER_NAME_LOC}
	, ${POSITION}
	, ${COUNTRY}
	, ${DATE_FORMAT}
	, ${EMAIL}
	, ${HOUSE_CODE}
	, UPPER(${USER_ID})
	, '1000'
	, 'SEPOA'
	, 'Y'
	, ${current.DATE}
	, 'N'
	, 'MUP190300001'
	, 'A'
	, 'Z'
	, ${PASSWORD}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
)


INSERT INTO SADDR
(
	  PHONE_NO1
	, PHONE_NO2
	, ZIP_CODE
	, ADDRESS_LOC
	, HOUSE_CODE
	, CODE_NO
	, CODE_TYPE
	, DEL_FLAG
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
) VALUES
(
	  ${PHONE_NO1}
	, ${PHONE_NO2}
	, ${ZIP_CODE}
	, ${ADDRESS_LOC}
	, ${HOUSE_CODE}
	, UPPER(${USER_ID})
	, 'USER'
	, 'N'
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
)


UPDATE
	SUSMT
SET
	  CHANGE_DATE = ${current.DATE}
	, CHANGE_TIME = ${current.TIME}
	, CHANGE_USER_ID = ${session.ID}
	, DEL_FLAG = 'N'
WHERE
	1=1
AND HOUSE_CODE = ${HOUSE_CODE}
AND USER_ID = ${USER_ID}


UPDATE
	SUSMT
SET
	  DEL_FLAG = 'Y'
	, CHANGE_DATE = ${current.DATE}
	, CHANGE_TIME = ${current.TIME}
	, CHANGE_USER_ID = ${session.ID}
WHERE
	1=1
AND HOUSE_CODE = ${HOUSE_CODE}
AND	USER_ID = ${USER_ID}


UPDATE
	SADDR
SET
	  DEL_FLAG = 'Y'
	, CHANGE_DATE = ${current.DATE}
	, CHANGE_TIME = ${current.TIME}
	, CHANGE_USER_ID = ${session.ID}
WHERE
	1=1
AND HOUSE_CODE = ${HOUSE_CODE}
AND	CODE_NO = ${USER_ID}
